    final Library library = getLibrary();
    if (library == null)
    {
      return false;
    }

    Document foundDocument = null;
    for (Document document : library.getDocuments())
    {
      if (bookTitle.equals(document.getTitle()))
      {
        foundDocument = document;
        break;
      }
    }

    if (!(foundDocument instanceof Book))
    {
      return false;
    }

    Book book = (Book)foundDocument;

    for (Member member : library.getMembers())
    {
      for (BorrowRecord record : member.getBorrowRecords())
      {
        if (record.getBook() == book)
        {
          return false;
        }
      }
    }

    if (getBorrowRecords().size() >= 3)
    {
      return false;
    }

    BorrowRecord newBorrowRecord = MunicipalLibraryFactory.eINSTANCE.createBorrowRecord();
    newBorrowRecord.setBorrowingDate(today);

    Date returnDue = new Date(today.getTime());
    returnDue.setTime(returnDue.getTime() + 7L * 24L * 60L * 60L * 1000L);
    newBorrowRecord.setReturnDue(returnDue);
    newBorrowRecord.setBook(book);

    getBorrowRecords().add(newBorrowRecord);
    return true;
    
